const { v4: uuidv4 } = require('uuid');
const input = $input.item.json;

return {
  json: {
    migrationId: uuidv4(),
    repoRN: input.repoRN,
    repoNative: input.repoNative || null,
    monorepoUrl: input.monorepoUrl,
    strategy: input.strategy || { startStage: 1, endStage: 3 },
    platforms: input.platforms || ['ios', 'android', 'web'],
    reviewers: input.reviewers || ['shlapolosa'],
    targetBranch: input.targetBranch || 'main',
    createdAt: new Date().toISOString()
  }
};

const fs = require('fs');
const path = '/tmp/migrations/' + $json.migrationId;
const inventory = $json.inventory;
const riskMatrix = $json.riskMatrix;

// Write inventory.json
fs.writeFileSync(
  path + '/docs/migration/inventory.json',
  JSON.stringify(inventory, null, 2)
);

// Write risk-matrix.md
let mdContent = '# Risk Matrix\n\n';
mdContent += '| Component | Risk | Complexity | Priority | Usage Count |\n';
mdContent += '|-----------|------|-----------|----------|-------------|\n';

riskMatrix.forEach(item => {
  mdContent += `| ${item.component} | ${item.risk} | ${item.complexity} | ${item.priority} | ${item.usageCount} |\n`;
});

fs.writeFileSync(
  path + '/docs/migration/risk-matrix.md',
  mdContent
);

return { json: $json };

// Check if this is the right migration
const expectedMigrationId = $('Save PR Info').first().json.migrationId;
const receivedMigrationId = $input.item.json.migrationId;

if (expectedMigrationId !== receivedMigrationId) {
  throw new Error('Wrong migration ID');
}

return { json: $input.item.json };
